function openReport(id){S.reportCamp=id;render();}function closeReport(){S.reportCamp=null;render();}function reportFolders(camps){camps=(camps||[]).slice().sort(function(a,b){return String(a.brand_name||"").localeCompare(String(b.brand_name||""),"ko");});var head=pageHeader("REPORT","인사이트 리포트","캠페인 폴더를 선택하세요");var f=camps.map(function(a){var w=wfOf(a),u=(w&&w.urls)||{},n=String((u.yt||"")+"\n"+(u.ig||"")+"\n"+(u.tt||"")).split(/\n+/).filter(function(s2){return s2.trim();}).length;return `<button onclick="openReport('${a.id}')" class="${CARD} p-5 flex items-center gap-3 text-left hover:shadow-md transition-all"><div class="w-12 h-12 rounded-2xl bg-blue-tint grid place-items-center flex-shrink-0"><i data-lucide="folder" class="w-6 h-6 text-blue"></i></div><div class="min-w-0"><p class="text-[16px] font-bold text-g900 truncate">${esc(a.brand_name||"캠페인")}</p><p class="text-[13px] text-g500">링크 ${n}개</p></div></button>`;}).join("");return `<div class="p-8 md:p-10">${head}<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-3 max-w-3xl">${f}</div></div>`;}function viewReport(){var _camps=(S.myCamps||[]).filter(function(a){return a.status==="승인 완료";});if(!S.reportCamp&&_camps.length){return reportFolders(_camps);}const c=S.reportCamp?(_camps.find(function(a){return String(a.id)===String(S.reportCamp);})||S.activeCamp):S.activeCamp;const wf=c?wfOf(c):{};const urls=wf.urls||{};const _su=function(s){return String(s||"").split(/\n+/).map(function(x){return x.trim();}).filter(Boolean).slice(0,10);};const list=[];[["YouTube",urls.yt,"text-red-500"],["Instagram",urls.ig,"text-pink-500"],["TikTok",urls.tt,"text-g800"]].forEach(function(pl){_su(pl[1]).forEach(function(u2,ix){list.push([pl[0]+(ix?" "+(ix+1):""),u2,pl[2]]);});});
const head=pageHeader("REPORT","인사이트 리포트",c?esc(c.brand_name)+" 캠페인":"")+(S.reportCamp&&S.view!=="admin-report"?`<button onclick="closeReport()" class="inline-flex items-center gap-1 text-[14px] font-bold text-g500 mb-4"><i data-lucide="arrow-left" class="w-4 h-4"></i>캠페인 목록</button>`:"");
if(!list.length)return `<div class="p-8 md:p-10">${head}<div class="max-w-xl"><div class="${CARD} p-14 text-center"><div class="w-14 h-14 rounded-[20px] bg-g100 grid place-items-center mx-auto mb-5"><i data-lucide="bar-chart-3" class="w-7 h-7 text-g300"></i></div><p class="text-[18px] font-bold text-g900 mb-1.5">업로드 완료 후 리포트가 제공됩니다</p><p class="text-[16px] text-g500 mb-5">크놀AD가 영상을 업로드하면 영상 URL·썸네일·조회수 인사이트가 여기에 표시됩니다.</p><div class="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-amber-50"><i data-lucide="clock" class="w-3.5 h-3.5 text-amber-600"></i><span class="text-[15px] font-bold text-amber-700">업로드 대기중</span></div></div></div><p class="text-[13px] text-g500 mt-4 leading-relaxed max-w-3xl">※ 틱톡·인스타그램 미러링 업로드는 서비스로 제공되는 항목으로, 영상 링크만 전달되며 인사이트는 별도 제공되지 않습니다.</p></div>`;
const cards=list.map(x=>{const vid=x[0].indexOf("YouTube")===0?ytId(x[1]):null;const thumb=vid?`<img src="https://i.ytimg.com/vi/${vid}/hqdefault.jpg" referrerpolicy="no-referrer" class="w-full aspect-video object-cover rounded-2xl mb-3" onerror="this.style.display='none'">`:`<div class="w-full aspect-video bg-g100 rounded-2xl mb-3 grid place-items-center text-g400"><i data-lucide="play-circle" class="w-10 h-10"></i></div>`;
return `<div class="${CARD} p-5">${thumb}<div class="flex items-center justify-between mb-3"><span class="font-bold ${x[2]}">${x[0]}</span><button onclick="openLink('${esc(x[1])}')" class="text-blue text-[13px] font-bold">영상 열기 ↗</button></div><p class="text-[12px] text-g400 truncate -mt-1 mb-3">${esc(x[1])}</p><div class="grid grid-cols-3 gap-2">${[].map(sx=>`<div class="bg-g50 rounded-xl p-3 text-center"><p class="text-[12px] text-g400">${sx[0]}</p><p class="text-[18px] font-bold text-g900 num">${sx[1]}</p></div>`).join("")}</div></div>`;}).join("");
return `<div class="p-8 md:p-10">${head}<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4 max-w-5xl">${cards}</div>${(function(){var yt=String(urls.yt||"").trim();if(!yt)return "";var draw=(wf.uploadedAt)||(c&&(c.approved_at||c.created_at))||null;var days=null;if(draw){var diff=Math.floor((Date.now()-new Date(draw).getTime())/86400000);days=14-diff;}var _ins=(wf.insights&&wf.insights.length)?wf.insights:null;var img=wf.insightImg||_ins||null;var body;if(_ins){body=_ins.map(function(v,i){return '<div class="mb-5"><p class="text-[13px] font-bold text-g700 mb-2">🎬 영상 '+(i+1)+(v.yt?' · <a href="'+esc(v.yt)+'" target="_blank" class="text-blue underline">열기 ↗</a>':'')+'</p>'+(/\.(jpe?g|png|gif|webp|bmp|svg|avif)(\?|$)/i.test(v.img||'')?('<img src="'+esc(v.img)+'" referrerpolicy="no-referrer" class="w-full rounded-2xl border border-g100">'):('<a href="'+esc(v.img)+'" target="_blank" class="flex items-center gap-2 bg-g50 rounded-2xl px-4 py-3 text-[14px] text-blue underline"><i data-lucide="file-archive" class="w-5 h-5 flex-shrink-0"></i><span class="truncate">'+esc(v.name||'압축파일 다운로드')+'</span></a>'))+'</div>';}).join('');}else if(img){body=`<img src="${esc(img)}" referrerpolicy="no-referrer" class="w-full rounded-2xl border border-g100"><p class="text-[12px] text-g400 mt-2">게시 이후 기준 · 좋아요·공유·추가된 댓글·순 시청자수·조회수</p>`;}else if(days!==null&&days>0){body=`<div class="text-center py-12 px-4 bg-g50 rounded-2xl"><div class="w-14 h-14 rounded-full bg-blue-tint grid place-items-center mx-auto mb-3"><i data-lucide="bar-chart-3" class="w-7 h-7 text-blue"></i></div><p class="text-[16px] font-bold text-g900 mb-1">상세 인사이트는 업로드 2주 뒤 제공 예정입니다</p><p class="text-[13px] text-g500">약 ${days}일 후 이 자리에 유튜브 상세 인사이트가 표시될 예정입니다</p></div>`;}else{body=`<div class="text-center py-12 px-4 bg-g50 rounded-2xl"><i data-lucide="loader-circle" class="w-8 h-8 text-blue mx-auto mb-2"></i><p class="text-[15px] font-bold text-g900">인사이트 준비 중입니다</p><p class="text-[13px] text-g500 mt-1">곧 상세 인사이트가 등록됩니다</p></div>`;}return `<div class="${CARD} p-5 mt-4 max-w-5xl"><div class="flex items-center gap-2 mb-3"><i data-lucide="youtube" class="w-5 h-5 text-red-500"></i><span class="font-bold text-g900">YouTube 상세 인사이트</span></div>${body}</div>`;})()}<p class="text-[13px] text-g500 mt-4 leading-relaxed max-w-3xl">※ 틱톡·인스타그램 미러링 업로드는 서비스로 제공되는 항목으로, 영상 링크만 전달되며 인사이트는 별도 제공되지 않습니다.</p></div>`;}


function viewCalendar(){setTimeout(loadMyCamps,30);const nd=new Date();if(S.calY==null){S.calY=nd.getFullYear();S.calM=nd.getMonth();}const y=S.calY,m=S.calM;
const startDow=new Date(y,m,1).getDay();const days=new Date(y,m+1,0).getDate();const todayStr=`${nd.getFullYear()}-${String(nd.getMonth()+1).padStart(2,'0')}-${String(nd.getDate()).padStart(2,'0')}`;
const ev=[];(S.myCamps||[]).forEach(a=>{if(a.preferred_date)[].push({date:a.preferred_date,title:(a.brand_name||'')+" 업로드",type:"auto",campId:a.id});});
const sch=(S.activeCamp&&S.activeCamp.schedule)||[];sch.forEach(e=>ev.push({date:e.date,title:e.title,type:"manual",id:e.id,cat:e.cat}));
let cells="";for(let i=0;i<startDow;i++)cells+='<div></div>';
for(let d=1;d<=days;d++){const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const isT=ds===todayStr;const es=ev.filter(e=>e.date===ds);
cells+=`<div onclick="calAdd('${ds}')" class="min-h-[120px] md:min-h-[140px] border ${isT?'border-transparent bg-blue-soft':'border-g100'} rounded-2xl p-2.5 cursor-pointer hover:bg-g50 transition-colors"><div class="text-[15px] font-bold ${isT?'text-blue':'text-g500'} mb-1">${d}</div>${es.map(e=>`<div onclick="event.stopPropagation();${e.type==='manual'?`calEdit('${e.id}')`:`calEditAuto('${e.campId}')`}" class="mb-1 text-[12px] px-2 py-1 rounded-lg truncate font-bold" style="${e.type==='auto'?'background:#EAF3FE;color:#1B64DA':calCatStyle(e.cat)}">${esc(e.title)}</div>`).join("")}</div>`;}
return `<div class="p-8 md:p-10">${pageHeader("SCHEDULE","캠페인 일정","업로드 일정은 담당 매니저가 등록·관리합니다 (보기 전용)")}
<div class="${CARD} p-6 md:p-8"><div class="flex items-center justify-between mb-5"><button onclick="calPrev()" class="w-10 h-10 rounded-full bg-g100 grid place-items-center text-g600 hover:bg-g200 text-[18px] font-bold">‹</button><h2 class="text-[22px] font-bold text-g900">${y}년 ${m+1}월</h2><button onclick="calNext()" class="w-10 h-10 rounded-full bg-g100 grid place-items-center text-g600 hover:bg-g200 text-[18px] font-bold">›</button></div>
<div class="grid grid-cols-7 gap-2 mb-2 text-center text-[14px] font-bold text-g400">${["일","월","화","수","목","금","토"].map(d=>`<div>${d}</div>`).join("")}</div>
<div class="grid grid-cols-7 gap-2">${cells}</div>
<div class="flex gap-4 mt-5 text-[13px] text-g500 flex-wrap"><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded bg-blue-tint"></span>업로드 예정 (신청값 자동)</span><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded" style="background:#FDF2F8;border:1px solid #DB2777"></span>콘티</span><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded" style="background:#FEF9C3;border:1px solid #A16207"></span>영상</span><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded" style="background:#ECFDF5;border:1px solid #047857"></span>업로드</span><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded" style="background:#EAF3FE;border:1px solid #3182F6"></span>정산</span><span class="inline-flex items-center gap-1.5"><span class="w-3 h-3 rounded bg-emerald-50 border border-emerald-200"></span>직접 추가한 일정</span></div></div></div>`;}
function calPrev(){if(S.calM==null){const d=new Date();S.calY=d.getFullYear();S.calM=d.getMonth();}S.calM--;if(S.calM<0){S.calM=11;S.calY--;}render();}
function calNext(){if(S.calM==null){const d=new Date();S.calY=d.getFullYear();S.calM=d.getMonth();}S.calM++;if(S.calM>11){S.calM=0;S.calY++;}render();}
function calForm(title,dateVal,titleVal,delId,saveArg){return `<div class="flex items-center justify-between mb-3"><h3 class="text-[18px] font-bold text-g900">${title}</h3><button onclick="closeModal()" class="w-8 h-8 rounded-full bg-g100 grid place-items-center text-g500">✕</button></div><label class="block text-[14px] font-bold text-g600 mb-1">날짜</label><input id="calDate" type="date" value="${dateVal}" class="${INPUT} mb-3"><label class="block text-[14px] font-bold text-g600 mb-1">일정 제목</label><input id="calTitle" value="${titleVal}" placeholder="예: 쇼잉 업로드, 콘티 마감" class="${INPUT} mb-4"><div class="flex gap-2">${delId?`<button onclick="calDelete('${delId}')" class="${BTN_GHOST} text-red-600 px-5">삭제</button>`:''}<button onclick="calSave(${saveArg})" class="${BTN} flex-1">저장</button></div>`;}
function calAdd(ds){toast("업로드 일정은 담당 매니저가 관리합니다");return;if(!S.activeCamp){toast("승인된 캠페인을 먼저 선택하세요");return;}modal(calForm("일정 추가",ds,"",null,"null"));}
function calEdit(id){toast("업로드 일정은 담당 매니저가 관리합니다");return;const c=S.activeCamp;const e=((c&&c.schedule)||[]).find(x=>x.id===id);if(!e)return;modal(calForm("일정 수정",e.date,esc(e.title),id,`'${id}'`));}
function calSave(id){const c=S.activeCamp;if(!c){toast("캠페인을 선택하세요");return;}const date=gv("calDate"),title=(gv("calTitle")||"").trim();if(!date||!title){toast("날짜와 제목을 입력하세요");return;}let sch=((c.schedule)||[]).slice();if(id){sch=sch.map(x=>x.id===id?{id:id,date:date,title:title}:x);}else{sch.push({id:"e"+Date.now(),date:date,title:title});}calPersist(c,sch,"일정이 저장되었습니다");}
function calDelete(id){const c=S.activeCamp;if(!c)return;calPersist(c,((c.schedule)||[]).filter(x=>x.id!==id),"일정이 삭제되었습니다");}
function calPersist(c,sch,msg){c.schedule=sch;fetch(SUPA_URL+"/rest/v1/knollad_applications?id=eq."+c.id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({schedule:sch})}).then(r=>{if(!r.ok)toast("저장 실패");}).catch(()=>toast("저장 오류"));closeModal();toast(msg);render();}
function calEditAuto(campId){return;const a=(S.myCamps||[]).find(x=>String(x.id)===String(campId));if(!a)return;modal(`<div class="flex items-center justify-between mb-3"><h3 class="text-[18px] font-bold text-g900 break-all">${esc(a.brand_name)} 업로드 희망일</h3><button onclick="closeModal()" class="w-8 h-8 rounded-full bg-g100 grid place-items-center text-g500">✕</button></div><p class="text-[13px] text-g500 mb-3">신청 시 입력한 업로드 희망일입니다. 변경하면 캠페인 정보에 반영됩니다.</p><input id="calDate" type="date" value="${esc(a.preferred_date||'')}" class="${INPUT} mb-4"><button onclick="calSaveAuto('${campId}')" class="${BTN} w-full">업로드 희망일 변경</button>`);}
function calSaveAuto(campId){const d=gv("calDate");const a=(S.myCamps||[]).find(x=>String(x.id)===String(campId));if(!a){return;}fetch(SUPA_URL+"/rest/v1/knollad_applications?id=eq."+campId,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({preferred_date:d})}).then(r=>{if(r.ok){a.preferred_date=d;toast("업로드 희망일이 변경되었습니다");}else toast("변경 실패");closeModal();render();}).catch(()=>toast("오류"));}
