function admInsightBar(a){var wf=(a&&a.wf)||{};var _insList=(wf.insights&&wf.insights.length)?wf.insights:(wf.insightImg?[{img:wf.insightImg}]:[]);var cur=_insList.length?_insList.map(function(v){return /\.(jpe?g|png|gif|webp|bmp|svg|avif)(\?|$)/i.test(v.img||'')?`<img src="${esc(v.img)}" referrerpolicy="no-referrer" class="w-full rounded-xl border border-g100 mb-2">`:`<a href="${esc(v.img)}" target="_blank" class="flex items-center gap-2 bg-g50 rounded-xl px-3 py-2 mb-2 text-[13px] text-blue underline"><i data-lucide="file-archive" class="w-4 h-4 flex-shrink-0"></i><span class="truncate">${esc(v.name||'압축파일 다운로드')}</span></a>`;}).join(""):"";return `<div class="mt-2 pt-2 border-t border-g100"><p class="text-[13px] font-bold text-g700 mb-1">📊 유튜브 인사이트 이미지·파일 <span class="text-g400 font-normal">(업로드 2주 후 고객 노출)</span></p>${cur}<input id="admInsight_${a.id}" type="file" accept="image/*,.zip,.rar,.7z,application/zip,application/x-zip-compressed,application/x-7z-compressed,application/x-rar-compressed" multiple class="block w-full text-[12px] text-g600 mb-2"><button onclick="admSaveInsight('${a.id}')" class="${BTN_GHOST} w-full mb-2">인사이트 이미지 저장</button></div>`;}
function admSaveInsight(id){var el=document.getElementById("admInsight_"+id);if(!(el&&el.files&&el.files.length)){toast("이미지를 선택해주세요");return;}var a=ADM_ROWS.find(function(x){return String(x.id)===String(id);});if(!a){toast("불러오기 실패");return;}toast("인사이트 이미지 업로드 중…");uploadFilesAll(el.files,function(arr){arr=arr||[];if(!arr.length||!arr[0].url){toast("업로드 실패 · 다시 시도해주세요");return;}var _newImgs=(arr||[]).filter(function(f){return f&&f.url;}).map(function(f){return {img:f.url,name:f.name};});var _prevInsights=((a.wf&&a.wf.insights)||[]).slice();var _allInsights=_prevInsights.concat(_newImgs);var wf=Object.assign({},(a.wf)||{step:2},{insights:_allInsights,insightImg:_allInsights.length?_allInsights[_allInsights.length-1].img:null,insightSrc:"manual",insightAt:new Date().toISOString()});fetch(SUPA_URL+"/rest/v1/knollad_applications?id=eq."+id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({wf:wf})}).then(function(r){if(r.ok){a.wf=wf;toast("인사이트 이미지가 저장되었습니다");if(typeof render==="function")render();}else toast("저장 실패");}).catch(function(){toast("오류");});});}
