function markReadMsg(camp,side){if(!camp||!camp.id)return;var notes=camp.notes||[];var other=side==="cust"?"knoll":"cust";var field=side==="cust"?"read_cust":"read_knoll";var cur=camp[field]||"";var hasNew=notes.some(function(n){var isOther=(n.role===other)||(other==="knoll"&&n.who==="크놀AD")||(other==="cust"&&(n.who==="고객"||n.role==="cust"));return isOther&&(!cur||String(n.at||"")>String(cur));});if(!hasNew)return;var now=new Date().toISOString();camp[field]=now;var body={};body[field]=now;fetch(SUPA_URL+"/rest/v1/knollad_applications?id=eq."+camp.id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify(body)}).catch(function(){});}
