/* ===== 성과 사례 관리 (admin-showcase) ===== */
var SC_ADM=null;
function scAdmLoad(){fetch(SUPA_URL+"/rest/v1/knollad_showcase?select=*&order=sort.asc,created_at.desc",{headers:SH}).then(function(r){return r.json();}).then(function(rows){SC_ADM=Array.isArray(rows)?rows:[];scAdmRender();}).catch(function(){SC_ADM=[];scAdmRender();});}
function viewAdminShowcase(){setTimeout(scAdmLoad,30);return `<div class="p-8 md:p-10">${pageHeader("SHOWCASE","성과 사례 관리","포트폴리오 페이지 상단 '성과 사례' 섹션에 노출됩니다 · 매출/주문 성과 캡처를 업로드하세요")}
<div class="${CARD} p-6 mb-6"><p class="text-[16px] font-bold text-g900 mb-4">새 사례 등록</p>
<div class="grid md:grid-cols-2 gap-3 mb-3"><input id="sc_title" placeholder="제목 (예: 건강식품 A사 — 2주 만에 매출 4,100만원)" class="${INPUT}"><input id="sc_brand" placeholder="브랜드/업종 (예: 건강식품 · A사)" class="${INPUT}"></div>
<textarea id="sc_note" rows="2" placeholder="설명 (예: 영상 업로드 직후 주문 2,331건 · 총매출 ₩41,039,179 · 노출 100만+)" class="${INPUT} mb-3"></textarea>
<div class="flex items-center gap-3 flex-wrap"><input id="sc_files" type="file" accept="image/*" multiple class="text-[14px]"><button onclick="scAdmAdd()" class="${BTN} px-6 py-3 text-[15px]"><i data-lucide="plus" class="w-4 h-4"></i>등록</button></div>
<p class="text-[12.5px] text-g400 mt-2">첫 번째 이미지가 카드 대표 이미지로 보입니다. 캡처에 고객 개인정보(이름·주소 등)가 없는지 확인 후 올려주세요.</p></div>
<div id="scAdmList"><p class="text-g400 text-[14px] py-6 text-center">불러오는 중…</p></div></div>`;}
function scAdmFind(id){return (SC_ADM||[]).find(function(x){return String(x.id)===String(id);});}
function scAdmPatch(id,body,cb){fetch(SUPA_URL+"/rest/v1/knollad_showcase?id=eq."+id,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify(body)}).then(function(r){if(cb)cb(r.ok);}).catch(function(){if(cb)cb(false);});}
function scAdmRender(){var box=document.getElementById("scAdmList");if(!box||!SC_ADM)return;if(!SC_ADM.length){box.innerHTML='<div class="'+CARD+' p-10 text-center text-g400">등록된 성과 사례가 없습니다</div>';return;}
box.innerHTML=SC_ADM.map(function(c){var im=(c.imgs&&c.imgs[0]);var iu=im?((im&&im.url)?im.url:im):null;return '<div class="'+CARD+' p-4 mb-3 flex items-center gap-4 flex-wrap">'+(iu?'<img src="'+esc(iu)+'" class="w-28 h-16 object-cover rounded-xl border border-g100 flex-shrink-0" style="object-position:left top">':'<div class="w-28 h-16 rounded-xl bg-g100 grid place-items-center text-g400 text-[12px] flex-shrink-0">없음</div>')+'<div class="flex-1 min-w-[200px]"><p class="font-bold text-g900">'+esc(c.title||"(제목 없음)")+'</p><p class="text-[13px] text-g400">'+esc(c.brand||"")+' · 이미지 '+((c.imgs||[]).length)+'장 · '+(c.visible?"노출 중":"숨김")+'</p></div><div class="flex items-center gap-2 flex-shrink-0">'
+'<button onclick="scAdmMove(\''+c.id+'\',-1)" class="w-9 h-9 rounded-xl bg-g100 grid place-items-center hover:bg-g200" title="위로"><i data-lucide="arrow-up" class="w-4 h-4"></i></button>'
+'<button onclick="scAdmMove(\''+c.id+'\',1)" class="w-9 h-9 rounded-xl bg-g100 grid place-items-center hover:bg-g200" title="아래로"><i data-lucide="arrow-down" class="w-4 h-4"></i></button>'
+'<button onclick="scAdmEdit(\''+c.id+'\')" class="px-4 py-2 rounded-xl bg-g100 font-bold text-[13.5px] hover:bg-g200">수정</button>'
+'<button onclick="scAdmVis(\''+c.id+'\')" class="px-4 py-2 rounded-xl '+(c.visible?'bg-blue-tint text-blue':'bg-g100 text-g500')+' font-bold text-[13.5px]">'+(c.visible?"노출":"숨김")+'</button>'
+'<button onclick="scAdmDel(\''+c.id+'\')" class="px-4 py-2 rounded-xl bg-red-100 text-red-500 font-bold text-[13.5px] hover:bg-red-200">삭제</button></div></div>';}).join("");if(window.lucide)lucide.createIcons();}
function scAdmAdd(){var t=(gv("sc_title")||"").trim();var fi=document.getElementById("sc_files");var files=(fi&&fi.files)?Array.prototype.slice.call(fi.files):[];if(!t){toast("제목을 입력하세요");return;}if(!files.length){toast("캡처 이미지를 선택하세요");return;}toast("이미지 업로드 중…");uploadFilesAll(files,function(arr){if(!arr.length){toast("업로드 실패");return;}var maxSort=0;(SC_ADM||[]).forEach(function(x){if((x.sort||0)>maxSort)maxSort=x.sort||0;});fetch(SUPA_URL+"/rest/v1/knollad_showcase",{method:"POST",headers:Object.assign({"Content-Type":"application/json","Prefer":"return=minimal"},SH),body:JSON.stringify({title:t,brand:(gv("sc_brand")||"").trim(),note:(gv("sc_note")||"").trim(),imgs:arr.map(function(f){return {url:f.url,name:f.name};}),sort:maxSort+1,visible:true})}).then(function(r){if(r.ok){toast("등록되었습니다");SC_LIST=null;render();}else toast("등록 실패");}).catch(function(){toast("오류");});});}
function scAdmVis(id){var c=scAdmFind(id);if(!c)return;scAdmPatch(id,{visible:!c.visible},function(ok){if(ok){c.visible=!c.visible;SC_LIST=null;scAdmRender();}else toast("변경 실패");});}
function scAdmDel(id){var c=scAdmFind(id);if(!c)return;if(!confirm("이 성과 사례를 삭제할까요?\n포트폴리오 페이지에서도 사라집니다."))return;fetch(SUPA_URL+"/rest/v1/knollad_showcase?id=eq."+id,{method:"DELETE",headers:Object.assign({"Prefer":"return=minimal"},SH)}).then(function(r){if(r.ok){SC_ADM=SC_ADM.filter(function(x){return String(x.id)!==String(id);});SC_LIST=null;toast("삭제되었습니다");scAdmRender();}else toast("삭제 실패");}).catch(function(){toast("오류");});}
function scAdmMove(id,dir){var arr=SC_ADM||[];var i=arr.findIndex(function(x){return String(x.id)===String(id);});var j=i+dir;if(i<0||j<0||j>=arr.length)return;var tmp=arr[i];arr[i]=arr[j];arr[j]=tmp;arr.forEach(function(x,k){x.sort=k+1;scAdmPatch(x.id,{sort:k+1});});SC_LIST=null;scAdmRender();}
function scAdmEdit(id){var c=scAdmFind(id);if(!c)return;var imgs=(c.imgs||[]).map(function(im,k){var iu=(im&&im.url)?im.url:im;return '<div class="relative inline-block mr-2 mb-2 align-top"><img src="'+esc(iu)+'" class="w-32 h-20 object-cover rounded-xl border border-g100" style="object-position:left top"><button onclick="scAdmImgDel(\''+c.id+'\','+k+')" class="absolute -top-2 -right-2 w-6 h-6 rounded-full bg-red-500 text-white text-[12px] font-bold">×</button></div>';}).join("");
modal('<div class="flex items-center justify-between mb-4"><h3 class="text-[20px] font-bold text-g900">사례 수정</h3><button onclick="closeModal()" class="w-9 h-9 rounded-xl bg-g100 grid place-items-center"><i data-lucide="x" class="w-4 h-4"></i></button></div>'
+'<label class="text-[12px] font-bold text-g500">제목</label><input id="sce_title" value="'+esc(c.title||"")+'" class="'+INPUT+' mb-3">'
+'<label class="text-[12px] font-bold text-g500">브랜드/업종</label><input id="sce_brand" value="'+esc(c.brand||"")+'" class="'+INPUT+' mb-3">'
+'<label class="text-[12px] font-bold text-g500">설명</label><textarea id="sce_note" rows="3" class="'+INPUT+' mb-4">'+esc(c.note||"")+'</textarea>'
+'<p class="text-[12px] font-bold text-g500 mb-2">이미지 (× 클릭 시 즉시 삭제)</p><div>'+(imgs||'<p class="text-[13px] text-g400 mb-2">이미지 없음</p>')+'</div>'
+'<p class="text-[12px] font-bold text-g500 mb-1 mt-2">이미지 추가</p><input id="sce_files" type="file" accept="image/*" multiple class="text-[13px] mb-4 block">'
+'<button onclick="scAdmSave(\''+c.id+'\')" class="'+BTN+' w-full py-3 text-[15px]">저장</button>',"max-w-2xl");}
function scAdmImgDel(id,k){var c=scAdmFind(id);if(!c)return;var imgs=(c.imgs||[]).slice();imgs.splice(k,1);scAdmPatch(id,{imgs:imgs},function(ok){if(ok){c.imgs=imgs;SC_LIST=null;scAdmEdit(id);scAdmRender();}else toast("삭제 실패");});}
function scAdmSave(id){var c=scAdmFind(id);if(!c)return;var fi=document.getElementById("sce_files");var files=(fi&&fi.files)?Array.prototype.slice.call(fi.files):[];var body={title:(gv("sce_title")||"").trim(),brand:(gv("sce_brand")||"").trim(),note:(gv("sce_note")||"").trim()};var fin=function(imgs){if(imgs)body.imgs=imgs;scAdmPatch(id,body,function(ok){if(ok){Object.assign(c,body);toast("저장되었습니다");SC_LIST=null;closeModal();scAdmRender();}else toast("저장 실패");});};if(files.length){toast("이미지 업로드 중…");uploadFilesAll(files,function(arr){fin((c.imgs||[]).concat(arr.map(function(f){return {url:f.url,name:f.name};})));});}else fin(null);}
function chatFileSize(n){if(n<1024)return n+"B";if(n<1024*1024)return (n/1024).toFixed(0)+"KB";return (n/1024/1024).toFixed(1)+"MB";}
function chatFileIcon(name,type){var e=String(name||"").split(".").pop().toLowerCase();
  if((type||"").indexOf("image")===0||["png","jpg","jpeg","gif","webp","heic","bmp"].indexOf(e)>=0)return ["image","#10B981","#ECFDF5"];
  if((type||"").indexOf("video")===0||["mp4","mov","avi","mkv","webm"].indexOf(e)>=0)return ["play","#4577F0","#EEF4FF"];
  if(e==="pdf")return ["file-text","#EF4444","#FEF2F2"];
  if(["xls","xlsx","csv"].indexOf(e)>=0)return ["table","#16A34A","#F0FDF4"];
  if(["ppt","pptx"].indexOf(e)>=0)return ["monitor","#F59E0B","#FFFBEB"];
  if(["zip","rar","7z"].indexOf(e)>=0)return ["archive","#8B95A1","#F2F4F6"];
  return ["file","#6B7684","#F2F4F6"];}
function chatFileName(inp,spanId){chatFileRender((inp&&inp.id)||String(spanId||"").replace(/Name$/,""));}
function chatFileRender(fid){try{var inp=document.getElementById(fid);var box=document.getElementById(fid+"Preview");var lab=document.getElementById(fid+"Name");if(!inp)return;
  var fs=inp.files?Array.prototype.slice.call(inp.files):[];
  if(lab){lab.textContent=fs.length?"":"선택된 파일 없음";lab.style.color="";}
  if(!box)return;
  if(!fs.length){box.innerHTML="";return;}
  var rows=fs.map(function(f,i){var ic=chatFileIcon(f.name,f.type);
    return '<div style="display:flex;align-items:center;gap:10px;padding:7px 0">'
     +'<span style="width:38px;height:38px;border-radius:11px;display:grid;place-items:center;flex-shrink:0;background:'+ic[2]+';color:'+ic[1]+'"><i data-lucide="'+ic[0]+'" style="width:18px;height:18px"></i></span>'
     +'<span style="flex:1;min-width:0"><span style="display:block;font-size:13.5px;font-weight:700;color:#191F28;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(f.name)+'</span>'
     +'<span style="display:block;font-size:12px;color:#8B95A1;margin-top:1px">'+chatFileSize(f.size)+'</span></span>'
     +'<button onclick="chatFileRemove(\''+fid+'\','+i+')" title="빼기" style="width:26px;height:26px;border-radius:8px;color:#B0B8C1;flex-shrink:0;font-size:13px;line-height:1">✕</button></div>';}).join("");
  box.innerHTML='<div style="background:#fff;border:1px solid #E5E8EB;border-radius:14px;padding:12px 12px 12px;margin-bottom:10px">'
   +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px"><span style="font-size:13.5px;font-weight:700;color:#191F28">파일 전송 <span style="color:#4577F0">'+fs.length+'</span></span>'
   +'<button onclick="chatFileClear(\''+fid+'\')" title="모두 빼기" style="width:26px;height:26px;border-radius:8px;color:#B0B8C1;font-size:13px;line-height:1">✕</button></div>'
   +rows
   +'<button onclick="chatSendNow(\''+fid+'\')" style="width:100%;height:42px;border-radius:10px;background:#4577F0;color:#fff;font-weight:600;font-size:14.5px;margin-top:8px">'+fs.length+'개 전송</button></div>';
  if(window.lucide)lucide.createIcons();}catch(e){}}
function chatFileRemove(fid,idx){try{var inp=document.getElementById(fid);if(!inp||!inp.files)return;var dt=new DataTransfer();var fs=inp.files;for(var i=0;i<fs.length;i++){if(i!==idx)dt.items.add(fs[i]);}inp.files=dt.files;chatFileRender(fid);}catch(e){}}
function chatFileClear(fid){try{var inp=document.getElementById(fid);if(!inp)return;inp.value="";try{inp.files=new DataTransfer().files;}catch(_e){}chatFileRender(fid);}catch(e){}}
function chatSendNow(fid){try{var box=document.querySelector('[data-chatdrop="'+fid+'"][data-chatsend]');var code=box?box.getAttribute("data-chatsend"):"";
  var kind=String(code||"").split("|")[0],arg=String(code||"").split("|")[1]||"";
  if(kind==="adm"&&typeof admSend==="function")admSend(arg);
  else if(kind==="wf"&&typeof wfSend==="function")wfSend();
  else if(kind==="cust"&&typeof chatSend==="function")chatSend();
  else toast("전송할 수 없습니다 · 새로고침 후 다시 시도해 주세요");}catch(e){toast("전송 오류 · 다시 시도해 주세요");}}

/* ===== 채팅 입력창: 파일 드래그&드롭 · 클립보드 붙여넣기 ===== */
function chatDropAdd(box,files){try{if(!box||!files||!files.length)return;var fid=box.getAttribute("data-chatdrop");var inp=document.getElementById(fid);if(!inp)return;
  var dt=new DataTransfer();var cur=inp.files;if(cur)for(var i=0;i<cur.length;i++)dt.items.add(cur[i]);
  for(var j=0;j<files.length;j++){var f=files[j];if(f&&f.size>=0)dt.items.add(f);}
  inp.files=dt.files;if(typeof chatFileRender==="function")chatFileRender(fid);
  if(typeof toast==="function")toast(files.length+"개 파일이 첨부되었습니다");}catch(e){}}
function chatDropStyle(box,on){try{if(!box)return;if(!box.dataset.dropBase){box.dataset.dropBase=(box.style.background||"")+"|"+(box.style.borderColor||"")+"|"+(box.style.boxShadow||"");}
  if(on){box.style.boxShadow="inset 0 0 0 2px #4577F0";}else{var b=(box.dataset.dropBase||"||").split("|");box.style.background=b[0];box.style.borderColor=b[1];box.style.boxShadow=b[2];}}catch(e){}}
(function(){var _dragBox=null;
 document.addEventListener("dragover",function(e){var box=e.target&&e.target.closest?e.target.closest("[data-chatdrop]"):null;if(!box)return;e.preventDefault();if(_dragBox!==box){chatDropStyle(_dragBox,false);_dragBox=box;chatDropStyle(box,true);}try{e.dataTransfer.dropEffect="copy";}catch(_e){}});
 document.addEventListener("dragleave",function(e){var box=e.target&&e.target.closest?e.target.closest("[data-chatdrop]"):null;if(box&&box===_dragBox&&!box.contains(e.relatedTarget)){chatDropStyle(box,false);_dragBox=null;}});
 document.addEventListener("drop",function(e){var box=e.target&&e.target.closest?e.target.closest("[data-chatdrop]"):null;if(!box)return;e.preventDefault();chatDropStyle(box,false);_dragBox=null;
   var f=e.dataTransfer&&e.dataTransfer.files;chatDropAdd(box,f);});
 document.addEventListener("paste",function(e){var ae=document.activeElement;if(!ae)return;var box=ae.closest?ae.closest("[data-chatdrop]"):null;if(!box)return;
   var items=e.clipboardData&&e.clipboardData.files;if(!items||!items.length)return;e.preventDefault();chatDropAdd(box,items);});
})();
function chatKeepClear(){try{S._chatKeep=S._chatKeep||{};for(var i=0;i<arguments.length;i++){var k=arguments[i];S._chatKeep[k]=null;var el=document.getElementById(k);if(el){if(el.tagName==="TEXTAREA")el.value="";else{try{el.value="";}catch(e){}}}}}catch(e){}}
function modalOpen(){try{var m=document.getElementById("modalRoot");return !!(m&&m.innerHTML.trim());}catch(e){return false;}}
